sources.content:
# create http api gateway
resource "aws_apigatewayv2_api" "http_api" {
  description = var.http_api_description
  name          = var.http_api_name
  protocol_type = "HTTP"
  tags = {
    Name = var.http_api_name
  }
  cors_configuration {
    allow_origins = ["*"]
    allow_methods = ["*"]
    allow_headers = ["*"]
  }
  disable_execute_api_endpoint = local.domain_enabled
}

# create http api gateway route
resource "aws_apigatewayv2_route" "http_api_route" {
  api_id    = aws_apigatewayv2_api.http_api.id
  authorization_type = "CUSTOM"
  authorizer_id = aws_apigatewayv2_authorizer.http_api_auth_authorizer.id
  route_key = "ANY /"
  target = "integrations/${aws_apigatewayv2_integration.http_api_integration.id}"
}

# create http api gateway integration
resource "aws_apigatewayv2_integration" "http_api_integration" {
  api_id           = aws_apigatewayv2_api.http_api.id
  integration_type = "AWS_PROXY"
  description      = "Mock Integration for ${var.http_api_name}"
  integration_method = "POST"
  integration_uri = aws_lambda_function.http_api_lambda.invoke_arn
  passthrough_behavior = "WHEN_NO_MATCH"
  payload_format_version = "2.0"
}

# create http api gateway stage
resource "aws_apigatewayv2_stage" "http_api_stage" {
  api_id = aws_apigatewayv2_api.http_api.id
  name   = var.http_api_stage
  auto_deploy = true
  default_route_settings {
    throttling_burst_limit   = var.throttling_burst_limit
    throttling_rate_limit    = var.throttling_rate_limit
  }
  tags = {
    Name = var.http_api_name
  }
}

# Lambda Authorizer
resource "aws_lambda_function" "http_api_auth_lambda" {
  function_name = var.auth_function_name
  role          = aws_iam_role.http_api_auth_lambda_role.arn
  handler       = "auth_function.lambda_handler"
  runtime       = var.function_runtime
  filename         = data.archive_file.http_api_auth_lambda_zip.output_path
  source_code_hash = filebase64sha256(data.archive_file.http_api_auth_lambda_zip.output_path)
  #environment variables
  environment {
    variables = {
        "SECRET_NAME" = aws_secretsmanager_secret.cf_api_header_secret_store.name
    }
  }
}

# API Gateway
resource "aws_apigatewayv2_authorizer" "http_api_auth_authorizer" {
  api_id                            = aws_apigatewayv2_api.http_api.id
  authorizer_type                   = "REQUEST"
  authorizer_uri                    = aws_lambda_function.http_api_auth_lambda.invoke_arn
  identity_sources                  = ["$request.header.x-origin-verify"]
  name                              = var.auth_function_name
  authorizer_payload_format_version = "2.0"
  authorizer_result_ttl_in_seconds = 0
}

# Zip Lambda code
data "archive_file" "http_api_auth_lambda_zip" {
  type        = "zip"
  source_file = "src/auth_function.py"
  output_path = "auth_function.zip"
}

# Lambda permission
resource "aws_lambda_permission" "http_api_auth_lambda_permission" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.http_api_auth_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http_api.execution_arn}/*/*"
}

# Lambda role
resource "aws_iam_role" "http_api_auth_lambda_role" {
  name = "http_api_auth_lambda_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "lambda.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}

# Lambda policies
resource "aws_iam_policy" "http_api_auth_lambda_logs_policy" {
  name        = "http_api_auth_lambda_policy"
  path        = "/"
  description = "http_api_auth_lambda_policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "arn:aws:logs:*:*:*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_policy" "http_api_auth_lambda_execution_policy" {
  name        = "http_api_auth_lambda_execution_policy"
  path        = "/"
  description = "http_api_auth_lambda_execution_policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "lambda:InvokeFunction"
      ],
      "Resource": "*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_policy" "http_api_auth_lambda_secret_policy" {
  name        = "http_api_auth_lambda_secret_policy"
  path        = "/"
  description = "http_api_auth_lambda_secret_policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "secretsmanager:GetSecretValue"
      ],
      "Resource": "${aws_secretsmanager_secret.cf_api_header_secret_store.arn}",
      "Effect": "Allow"
    }
  ]
}
EOF
}

# Lambda Auth policy attachments
resource "aws_iam_role_policy_attachment" "http_api_auth_lambda_log_policy_attachment" {
  role       = aws_iam_role.http_api_auth_lambda_role.name
  policy_arn = aws_iam_policy.http_api_auth_lambda_logs_policy.arn
}

resource "aws_iam_role_policy_attachment" "http_api_auth_lambda_execution_policy_attachment" {
  role       = aws_iam_role.http_api_auth_lambda_role.name
  policy_arn = aws_iam_policy.http_api_auth_lambda_execution_policy.arn
}

resource "aws_iam_role_policy_attachment" "http_api_auth_lambda_secret_policy_attachment" {
  role       = aws_iam_role.http_api_auth_lambda_role.name
  policy_arn = aws_iam_policy.http_api_auth_lambda_secret_policy.arn
}

# CloudFront distribution for HTTP API Gateway
resource "aws_cloudfront_distribution" "http_api_distribution" {
  origin {
    #if domain_name is not empty, domain_name else "${aws_apigatewayv2_api.http_api.id}.execute-api.${var.region}.amazonaws.com"
    domain_name = local.domain_enabled ? var.domain_name : "${aws_apigatewayv2_api.http_api.id}.execute-api.${var.region}.amazonaws.com"
    origin_id   = "http_api_origin"
    custom_origin_config {
      http_port              = "80"
      https_port             = "443"
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
    custom_header {
      name  = "X-Origin-Verify"
      value = var.cloudfront_api_secret_name
    }
    custom_header {
      name  = "X-Origin-Verify-Region"
      value = var.region
    }    
  }

  enabled = true

  aliases = local.cloudfront_domain_enabled ? [var.cloudfront_domain_name] : []

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "http_api_origin"

    forwarded_values {
      query_string = false
      headers      = ["Authorization"]

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = var.min_ttl
    default_ttl            = var.default_ttl
    max_ttl                = var.max_ttl

    lambda_function_association {
      event_type   = "origin-request"
      lambda_arn   = aws_lambda_function.http_api_edge_lambda.qualified_arn
      include_body = false
    }

  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  # Certificate settings when domain_name is not empty
  dynamic "viewer_certificate" {
    for_each = local.cloudfront_domain_enabled ? [1] : []
    content {
        acm_certificate_arn = local.cloudfront_domain_enabled ? var.cloudfront_certificate_arn : ""
        cloudfront_default_certificate = !local.cloudfront_domain_enabled
        ssl_support_method = "sni-only"
    }
  }

  # Certificate settings when domain_name is empty
  dynamic "viewer_certificate" {
    for_each = !local.cloudfront_domain_enabled ? [1] : []
    content {
        cloudfront_default_certificate = !local.cloudfront_domain_enabled
    }
  }

  web_acl_id = aws_wafv2_web_acl.cloudfront_web_acl.arn
}

# create api gateway custom domain
resource "aws_apigatewayv2_domain_name" "http_api_domain_name" {
  count = local.domain_enabled ? 1 : 0
  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = var.certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

# create api gateway mapping
resource "aws_apigatewayv2_api_mapping" "http_api_mapping" {
  count = local.domain_enabled ? 1 : 0
  api_id      = aws_apigatewayv2_api.http_api.id
  domain_name = aws_apigatewayv2_domain_name.http_api_domain_name[0].id
  stage       = aws_apigatewayv2_stage.http_api_stage.id
}

# create route53 record for api gateway custom domain
resource "aws_route53_record" "http_api_route53_record" {
  count = local.domain_enabled ? 1 : 0
  name    = aws_apigatewayv2_domain_name.http_api_domain_name[0].domain_name
  type    = "A"
  zone_id = var.zone_id

  alias {
    name                   = aws_apigatewayv2_domain_name.http_api_domain_name[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http_api_domain_name[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# create route53 record for cloudfront custom domain
resource "aws_route53_record" "cloudfront_route53_record" {
  count = local.cloudfront_domain_enabled ? 1 : 0
  name    = var.cloudfront_domain_name
  type    = "A"
  zone_id = var.zone_id

  alias {
    name = "${aws_cloudfront_distribution.http_api_distribution.domain_name}"
    zone_id = "${aws_cloudfront_distribution.http_api_distribution.hosted_zone_id}"
    evaluate_target_health = false
  }
}

# Lambda Edge
resource "aws_lambda_function" "http_api_edge_lambda" {
  function_name = var.edge_function_name
  role          = aws_iam_role.http_api_edge_lambda_role.arn
  handler       = "edge_function.lambda_handler"
  runtime       = var.function_runtime
  filename         = data.archive_file.http_api_edge_lambda_zip.output_path
  source_code_hash = filebase64sha256(data.archive_file.http_api_edge_lambda_zip.output_path)
  publish = true
  provider = aws.cloudfront
}

# Zip Lambda code
data "archive_file" "http_api_edge_lambda_zip" {
  type        = "zip"
  source_file = "src/edge_function.py"
  output_path = "edge_function.zip"
}

# Lambda permission
resource "aws_lambda_permission" "http_api_edge_lambda_permission" {
  statement_id  = "AllowCloudFrontEdgeInvoke"
  action        = "lambda:InvokeFunction"
  function_name = var.edge_function_name
  principal     = "cloudfront.amazonaws.com"
  source_arn    = aws_cloudfront_distribution.http_api_distribution.arn
  provider = aws.cloudfront
}

# Lambda role
resource "aws_iam_role" "http_api_edge_lambda_role" {
  name = "http_api_edge_lambda_role"
  provider = aws.cloudfront
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": [
            "lambda.amazonaws.com",
            "edgelambda.amazonaws.com"
        ]
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}

# Lambda policies
resource "aws_iam_policy" "http_api_edge_lambda_logs_policy" {
  name        = "http_api_edge_lambda_policy"
  path        = "/"
  description = "http_api_edge_lambda_policy"
  provider = aws.cloudfront
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "arn:aws:logs:*:*:*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_policy" "http_api_edge_lambda_execution_policy" {
  name        = "http_api_edge_lambda_execution_policy"
  path        = "/"
  description = "http_api_edge_lambda_execution_policy"
  provider = aws.cloudfront
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "lambda:InvokeFunction"
      ],
      "Resource": "*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_policy" "http_api_edge_lambda_secret_policy" {
  name        = "http_api_edge_lambda_secret_policy"
  path        = "/"
  description = "http_api_edge_lambda_secret_policy"
  provider = aws.cloudfront
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "secretsmanager:GetSecretValue"
      ],
      "Resource": "${aws_secretsmanager_secret.cf_api_header_secret_store.arn}",
      "Effect": "Allow"
    }
  ]
}
EOF
}

# Lambda Auth policy attachments
resource "aws_iam_role_policy_attachment" "http_api_edge_lambda_log_policy_attachment" {
  role       = aws_iam_role.http_api_edge_lambda_role.name
  policy_arn = aws_iam_policy.http_api_edge_lambda_logs_policy.arn
  provider = aws.cloudfront
}

resource "aws_iam_role_policy_attachment" "http_api_edge_lambda_execution_policy_attachment" {
  role       = aws_iam_role.http_api_edge_lambda_role.name
  policy_arn = aws_iam_policy.http_api_edge_lambda_execution_policy.arn
  provider = aws.cloudfront
}

resource "aws_iam_role_policy_attachment" "http_api_edge_lambda_secret_policy_attachment" {
  role       = aws_iam_role.http_api_edge_lambda_role.name
  policy_arn = aws_iam_policy.http_api_edge_lambda_secret_policy.arn
  provider = aws.cloudfront
}

# Secret rotation Lambda function
resource "aws_lambda_function" "secret_rotation_lambda" {
  function_name = var.secret_rotation_function_name
  memory_size   = var.secret_rotation_lambda_memory
  role          = aws_iam_role.secret_rotation_lambda_role.arn
  handler       = "secret_rotation_function.lambda_handler"
  runtime       = var.function_runtime
  filename         = data.archive_file.secret_rotation_lambda_zip.output_path
  source_code_hash = filebase64sha256(data.archive_file.secret_rotation_lambda_zip.output_path)
  #environment variables
  environment {
    variables = {
        "UNIQUE_KEY_LENGTH" = var.unique_key_length
    }
  }  
}

# Zip Lambda code
data "archive_file" "secret_rotation_lambda_zip" {
  type        = "zip"
  source_file = "src/secret_rotation_function.py"
  output_path = "secret_rotation_function.zip"
}

# Lambda permission
resource "aws_lambda_permission" "secret_rotation_lambda_permission" {
  statement_id  = "AllowSecretRotationInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.secret_rotation_lambda.function_name
  principal     = "secretsmanager.amazonaws.com"
  source_arn    = aws_secretsmanager_secret.cf_api_header_secret_store.arn
}

# Lambda role
resource "aws_iam_role" "secret_rotation_lambda_role" {
  name = "secret_rotation_lambda_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "lambda.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}

# Lambda policies
resource "aws_iam_policy" "secret_rotation_lambda_logs_policy" {
  name        = "secret_rotation_lambda_policy"
  path        = "/"
  description = "secret_rotation_lambda_policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "arn:aws:logs:*:*:*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_policy" "secret_rotation_lambda_execution_policy" {
  name        = "secret_rotation_lambda_execution_policy"
  path        = "/"
  description = "secret_rotation_lambda_execution_policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "lambda:InvokeFunction"
      ],
      "Resource": "*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_policy" "secret_rotation_secretsmgr_policy" {
  name        = "secret_rotation_secretsmgr_policy"
  path        = "/"
  description = "secret_rotation_secretsmgr_policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "secretsmanager:DescribeSecret",
        "secretsmanager:GetSecretValue",
        "secretsmanager:PutSecretValue",
        "secretsmanager:UpdateSecretVersionStage"
      ],
      "Resource": "${aws_secretsmanager_secret.cf_api_header_secret_store.arn}",
      "Effect": "Allow"
    },
    {
      "Action": [
        "secretsmanager:GetRandomPassword"
      ],
      "Resource": "*",
      "Effect": "Allow"
    }
  ]
}
EOF
}

# Lambda policy attachments
resource "aws_iam_role_policy_attachment" "secret_rotation_lambda_log_policy_attachment" {
  role       = aws_iam_role.secret_rotation_lambda_role.name
  policy_arn = aws_iam_policy.secret_rotation_lambda_logs_policy.arn
}

resource "aws_iam_role_policy_attachment" "secret_rotation_lambda_execution_policy_attachment" {
  role       = aws_iam_role.secret_rotation_lambda_role.name
  policy_arn = aws_iam_policy.secret_rotation_lambda_execution_policy.arn
}

