resource "aws_iam_role_policy_attachment" "http_api_lambda_execution_policy_attachment" {
  role       = aws_iam_role.http_api_lambda_role.name
  policy_arn = aws_iam_policy.http_api_lambda_execution_policy.arn
}

#aws provider
provider "aws" {
  region = var.region
}

#aws provider for resources dependent on us-east-1 region
#Lambda@Edge function must be deployed in us-east-1 region
#AWS WAF is available globally for CloudFront distributions, but you must use us-east-1
#to create your web ACL and any resources used in the web ACL, such as rule groups, IP sets, and regex pattern sets
provider "aws" {
  alias  = "cloudfront"
  region = "us-east-1"
}

#get current caller identity
data "aws_caller_identity" "current" {}

#local variables
locals {
  account_id = data.aws_caller_identity.current.account_id
  cloudfront_domain_enabled = (var.cloudfront_domain_name != "")
  domain_enabled = (var.domain_name != "")
}

# api gateway endpoint output
output "api_gateway_endpoint" {
  value = aws_apigatewayv2_api.http_api.api_endpoint
}

# cloudfront distribution output
output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.http_api_distribution.domain_name
}

# cloudfront domain name
output "cloudfront_domain_name" {
  value = var.cloudfront_domain_name
}

# domain name
output "domain_name" {
  value = var.domain_name
}

# Secret store for CloudFront header
resource "aws_secretsmanager_secret" "cf_api_header_secret_store" {
  name = var.cloudfront_api_secret_name
  description = "CloudFront secret"
}

# Secret value for CloudFront header
resource "aws_secretsmanager_secret_version" "cf_api_header_secret_value" {
  secret_id     = aws_secretsmanager_secret.cf_api_header_secret_store.id
  secret_string = random_id.secret_random_value.hex
}

# Random value for CloudFront header
resource "random_id" "secret_random_value" {
    byte_length = var.unique_key_length
}

# Secret rotation
resource "aws_secretsmanager_secret_rotation" "cf_api_header_secret_store_rotation" {
  secret_id           = aws_secretsmanager_secret.cf_api_header_secret_store.id
  rotation_lambda_arn = aws_lambda_function.secret_rotation_lambda.arn

  rotation_rules {
    automatically_after_days = 30
  }
}

variable "http_api_description" {
  type = string
  default = "WAF HTTP API"
}

variable "http_api_name" {
  type = string
  default = "waf-http-api"
}

variable "http_api_stage" {
  type = string
  default = "$default"
}

variable "function_name" {
  type = string
  default = "http-api-lambda"
}

variable "auth_function_name" {
  type = string
  default = "http-auth-lambda"
}

variable "edge_function_name" {
  type = string
  default = "http-edge-lambda"
}

